import React, { useState, useEffect } from "react";
import axios from "axios";

function MERNApp() {
  const [items, setItems] = useState([]);
  const [formData, setFormData] = useState({ name: "", email: "", role: "" });
  const [editingItem, setEditingItem] = useState(null);

  const fetchUsers = async () => {
    const res = await axios.get("http://localhost:5000/api/users");
    setItems(res.data);
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleCreate = async () => {
    if (!formData.name || !formData.email || !formData.role) return alert("Fill all fields");
    const res = await axios.post("http://localhost:5000/api/users", formData);
    setItems([...items, res.data]);
    setFormData({ name: "", email: "", role: "" });
  };

  const handleUpdate = async () => {
    const res = await axios.put(`http://localhost:5000/api/users/${editingItem._id}`, formData);
    setItems(items.map((i) => (i._id === editingItem._id ? res.data : i)));
    setEditingItem(null);
    setFormData({ name: "", email: "", role: "" });
  };

  const handleDelete = async (id) => {
    if (window.confirm("Delete this user?")) {
      await axios.delete(`http://localhost:5000/api/users/${id}`);
      setItems(items.filter((i) => i._id !== id));
    }
  };

  const handleEdit = (item) => {
    setEditingItem(item);
    setFormData({ name: item.name, email: item.email, role: item.role });
  };

  return (
    <div style={{ maxWidth: 600, margin: "50px auto", textAlign: "center" }}>
      <h1>MERN User Manager</h1>

      <input
        type="text"
        name="name"
        placeholder="Name"
        value={formData.name}
        onChange={handleChange}
      /><br />
      <input
        type="email"
        name="email"
        placeholder="Email"
        value={formData.email}
        onChange={handleChange}
      /><br />
      <input
        type="text"
        name="role"
        placeholder="Role"
        value={formData.role}
        onChange={handleChange}
      /><br /><br />

      {editingItem ? (
        <button onClick={handleUpdate}>Update</button>
      ) : (
        <button onClick={handleCreate}>Add User</button>
      )}

      <h2 style={{ marginTop: 40 }}>User List</h2>
      <ul style={{ listStyle: "none", padding: 0 }}>
        {items.map((item) => (
          <li key={item._id} style={{ margin: "10px 0", borderBottom: "1px solid #ccc" }}>
            <b>{item.name}</b> ({item.role}) <br />
            {item.email} <br />
            <button onClick={() => handleEdit(item)}>Edit</button>
            <button onClick={() => handleDelete(item._id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default MERNApp;
